<template><view><view class="card"><view class="section-title">微态自测</view><view class="muted">每日记录排便、睡眠、压力、饮食等变化。</view><textarea v-model="note" placeholder="记录今日体感" class="area"/><button class="green-btn" @tap="submit">提交记录</button><view v-for="r in records" :key="r.id" class="record">{{ r.adviceSummary || r.answerJson }}</view></view></view></template>
<script setup>import { ref,onMounted } from 'vue'; import { api } from '@/api/index'; const note=ref(''); const records=ref([]); async function load(){ records.value=await api.selfTests() } async function submit(){ await api.submitSelfTest({version:'V1.1', symptomTags:'daily', behaviorTags:'self', stoolStatus:'normal', sleepStatus:'normal', pressureLevel:'medium', answerJson: JSON.stringify({note:note.value})}); uni.showToast({title:'已记录'}); note.value=''; await load() } onMounted(load)</script>
<style scoped>.area{width:100%;height:180rpx;background:#f8fcf9;border-radius:18rpx;padding:20rpx;box-sizing:border-box}.record{margin-top:18rpx;background:#f8fcf9;padding:18rpx;border-radius:16rpx}</style>
